import { Option } from "effect";

import type {
  InventoryAttribute,
  InventoryChild,
  InventoryLeaf,
} from "#pantry/schema/content/xsd-inventory.ts";

/**
 * Build an attribute row from its declaration.
 *
 * @param name - The attribute name as the XSD spells it.
 * @param type - The declared type name, or the base of an inline type.
 * @param use - Whether the XSD requires the attribute.
 * @param whiteSpace - The `whiteSpace` class of the declared type.
 * @returns The attribute row, of the MathML family `own` with no default.
 */
const attribute = (
  name: string,
  type: string,
  use: InventoryAttribute["use"],
  whiteSpace: InventoryAttribute["whiteSpace"],
): InventoryAttribute => ({
  default: Option.none(),
  family: "own",
  name,
  type,
  use,
  whiteSpace,
});

/**
 * Build a child row from an element reference.
 *
 * @param name - The referenced element's handle.
 * @param min - The effective minimum occurrence.
 * @param max - The effective maximum occurrence, `None` when unbounded.
 * @returns The child row.
 */
const child = (name: string, min: number, max: Option.Option<number>): InventoryChild => ({
  max,
  min,
  name,
});

/**
 * An element wildcard: the `xs:any` a model holds, with its occurrence.
 */
export interface MathmlElementWildcard {
  readonly namespace: string;
  readonly process: "lax" | "skip" | "strict";
  readonly min: number;
  readonly max: number;
}

/**
 * An attribute wildcard: the `xs:anyAttribute` the listed kinds carry.
 */
export interface MathmlAttributeWildcard {
  readonly namespace: string;
  readonly process: "lax" | "skip" | "strict";
  readonly kinds: readonly string[];
}

/**
 * The wildcards of the MathML XSD.
 */
export interface MathmlWildcards {
  readonly element: { readonly [handle: string]: MathmlElementWildcard };
  readonly attribute: MathmlAttributeWildcard;
}

